      { t = "Al este de la abadía, mata matones Defias para [Hermandad de ladrones]. Vuelve con Ayudante del alguacil Willem: entrégala y acepta [La recompensa por Garrick Piesuaves] y [Milly Osworth].", wp = { { m = 1429, z = "Bosque de Elwynn", x = 54.3, y = 47.0, n = "Objetivo: Hermandad de ladrones", q = 18, a = "C" }, { m = 1429, z = "Bosque de Elwynn", x = 48.2, y = 42.9, n = "Entregar: Hermandad de ladrones (Ayudante del alguacil Willem)", q = 18, a = "T" }, { m = 1429, z = "Bosque de Elwynn", x = 48.2, y = 42.9, n = "Recoger: La recompensa por Garrick Piesuaves (Ayudante del alguacil Willem)", q = 6, a = "A" }, { m = 1429, z = "Bosque de Elwynn", x = 48.2, y = 42.9, n = "Recoger: Milly Osworth (Ayudante del alguacil Willem)", q = 3903, a = "A" } } },
