      { t = "Vuelve a la abadía: entrega [La cosecha de Milly] y lleva [Informe de la vendimia] a Hermano Neals. Entrega [La recompensa por Garrick Piesuaves] a Ayudante del alguacil Willem y, en el establo de detrás, [¡Sigue a ese kóbold!] a Tordrin Sternblade: acepta [¡Chis! Estamos cazando kóbolds].", wp = { { m = 1429, z = "Bosque de Elwynn", x = 50.7, y = 39.4, n = "Entregar: La cosecha de Milly (Milly Osworth)", q = 3904, a = "T" }, { m = 1429, z = "Bosque de Elwynn", x = 50.7, y = 39.4, n = "Recoger: Informe de la vendimia (Milly Osworth)", q = 3905, a = "A" }, { m = 1429, z = "Bosque de Elwynn", x = 49.5, y = 41.6, n = "Entregar: Informe de la vendimia (Hermano Neals)", q = 3905, a = "T" }, { m = 1429, z = "Bosque de Elwynn", x = 48.2, y = 42.9, n = "Entregar: La recompensa por Garrick Piesuaves (Ayudante del alguacil Willem)", q = 6, a = "T" }, { m = 1429, z = "Bosque de Elwynn", x = 51.2, y = 40.8, n = "Entregar: ¡Sigue a ese kóbold! (Tordrin Hojadusta)", q = 91758, a = "T" }, { m = 1429, z = "Bosque de Elwynn", x = 51.2, y = 40.8, n = "Recoger: ¡Chis! Estamos cazando kóbolds (Tordrin Hojadusta)", q = 91772, a = "A" } } },
