  {
    titulo = "Ventormenta", min = 10, max = 11,
    entrenar = "En Ventormenta tus instructores de cazador están en el Distrito de los Enanos: Ulfir Barbaférrea, con Karrina Mekenda para tu mascota; en Forjaz, Olmin Barbanllamas y Belia Tronagranito, en el Barrio Militar. Dale de comer a tu mascota con Alimentar mascota cuando esté descontenta: el oso come pan, carne, pescado, queso, fruta y hongos (los taberneros venden pan). Talentos: 10-14 Aspectos letales.",
    equipo = "En el Distrito de Mercaderes de Ventormenta, Lina Paladare vende arcos y flechas, y Woo Ping, en la misma calle, enseña Bastones: la guía te recomienda arcos, dagas y bastones. Mira también la subasta: un buen arco es tu mayor mejora de daño.",
    profesion = "Minería y Desuello a 50: rango oficial con Gelman Petramano y Maris Granger en Ventormenta, o con Geofram Dedorroca y Balthus Cazarrocas en Forjaz. Primeros auxilios con Shaina Fuller, en la Plaza de la Catedral: <Venda de lino>.",
    pasos = {
      { t = "Sigue el camino al norte hasta Ventormenta. En el Distrito de Mercaderes activa el vuelo con Dungar Tragolargo y entrega [Un envío para Ventormenta] a Morgan Mortero.", wp = { { m = 1453, z = "Ciudad de Ventormenta", x = 71.3, y = 72.2, n = "Dungar Tragolargo", npc = 352 }, { m = 1453, z = "Ciudad de Ventormenta", x = 63.2, y = 74.4, n = "Entregar: Un envío para Ventormenta (Morgan Mortero)", q = 61, a = "T" } } },
      { t = "En el Distrito de Mercaderes, Woo Ping enseña Bastones: apréndelos si quieres llevar un arma de dos manos por sus estadísticas. Cerca, Lina Paladare vende arcos y flechas.", wp = { { m = 1453, z = "Ciudad de Ventormenta", x = 63.9, y = 69.1, n = "Woo Ping", npc = 11867 }, { m = 1453, z = "Ciudad de Ventormenta", x = 58.7, y = 68.7, n = "Lina Paladare", npc = 1297 } } },
      { t = "Con 50 de desuello, aprende el rango oficial con Maris Granger, en el Casco Antiguo; con 50 de minería, con Gelman Petramano, en el Distrito de los Enanos. En la Plaza de la Catedral, Shaina Fuller enseña Primeros auxilios.", wp = { { m = 1453, z = "Ciudad de Ventormenta", x = 72.1, y = 62.2, n = "Maris Granger", npc = 1292 }, { m = 1453, z = "Ciudad de Ventormenta", x = 53.0, y = 44.7, n = "Shaina Fuller", npc = 2327 }, { m = 1453, z = "Ciudad de Ventormenta", x = 59.2, y = 37.8, n = "Gelman Petramano", npc = 5513 } }, comprobar = { oficios = { 129 } } },
    },
  },
  {
    titulo = "Páramos de Poniente", min = 11, max = 15,
    entrenar = "Nivel 20 = gran entrenamiento en Ventormenta con Ulfir Barbaférrea, en el Distrito de los Enanos: Disparo de puntería (en Forever lo vende el instructor: ábrelo cada combate con él), Aspecto del guepardo (para viajar), Separación, Trampa congelante, Disparo Arcano (rango 3) y Aliviar mascota (rango 2); con Karrina Mekenda, al lado, Gruñido (rango 3) para tu mascota. Talento 20: Rapidez de bestias (tu mascota corre más).",
    equipo = "Objetivo: completar la cadena [La hermandad de los Defias] hasta Las Minas de la Muerte. En la Colina del Centinela, William MacGregor vende arcos y flechas.",
    profesion = "Desuello: lobos, jabalíes y buitres de Poniente dan <Cuero ligero> y <Cuero medio>. Minería: cobre y estaño en las colinas. Primeros auxilios: <Venda de lana>.",
    pasos = {
      { t = "Sigue el camino al oeste por Elwynn hasta Poniente (desde Ventormenta, sal por el Valle de los Héroes). Al entrar, en la granja de los Cejade, Verna Cejade te da [Estofado de los Páramos de Poniente] y [La pobre y vieja Blanchy], y Granjero Cejade, [La reliquia olvidada].", wp = { { m = 1436, z = "Páramos de Poniente", x = 59.9, y = 19.4, n = "Recoger: Estofado de los Páramos de Poniente (Verna Cejade)", q = 36, a = "A" }, { m = 1436, z = "Páramos de Poniente", x = 59.9, y = 19.4, n = "Recoger: La pobre y vieja Blanchy (Verna Cejade)", q = 151, a = "A" }, { m = 1436, z = "Páramos de Poniente", x = 60.0, y = 19.4, n = "Recoger: La reliquia olvidada (Granjero Cejade)", q = 64, a = "A" } } },
      { t = "Granja de los Saldean, al sur por el camino: entrega [Estofado de los Páramos de Poniente] a Salma Saldean y acepta [Estofado de los Páramos de Poniente] y [Pastel de hígado de dentosangre]. Granjero Saldean te da [Campos de la muerte].", wp = { { m = 1436, z = "Páramos de Poniente", x = 56.4, y = 30.5, n = "Entregar: Estofado de los Páramos de Poniente (Salma Saldean)", q = 36, a = "T" }, { m = 1436, z = "Páramos de Poniente", x = 56.4, y = 30.5, n = "Recoger: Estofado de los Páramos de Poniente (Salma Saldean)", q = 38, a = "A" }, { m = 1436, z = "Páramos de Poniente", x = 56.4, y = 30.5, n = "Recoger: Pastel de hígado de dentosangre (Salma Saldean)", q = 22, a = "A" }, { m = 1436, z = "Páramos de Poniente", x = 56.0, y = 31.2, n = "Recoger: Campos de la muerte (Granjero Saldean)", q = 9, a = "A" } } },
      { t = "Por los campos de alrededor: mata gólems de la cosecha ([Campos de la muerte]), jabalíes dentosangre (hígados de [Pastel de hígado de dentosangre]) y buitres, jabalíes y arañas para la carne de [Estofado de los Páramos de Poniente]. Recoge también las avenas de [La pobre y vieja Blanchy] y busca la reliquia de [La reliquia olvidada] donde te marca la flecha.", wp = { { m = 1436, z = "Páramos de Poniente", x = 53.5, y = 31.7, n = "Objetivo: Campos de la muerte", q = 9, a = "C" }, { m = 1436, z = "Páramos de Poniente", x = 56.0, y = 43.1, n = "Objetivo: Pastel de hígado de dentosangre", q = 22, a = "C" }, { m = 1436, z = "Páramos de Poniente", x = 53.4, y = 22.9, n = "Objetivo: Estofado de los Páramos de Poniente", q = 38, a = "C" }, { m = 1436, z = "Páramos de Poniente", x = 56.1, y = 17.3, n = "Objetivo: La pobre y vieja Blanchy", q = 151, a = "C" }, { m = 1436, z = "Páramos de Poniente", x = 49.3, y = 19.3, n = "Objetivo: La reliquia olvidada", q = 64, a = "C" } } },
      { t = "Entrega [Campos de la muerte], [Pastel de hígado de dentosangre] y [Estofado de los Páramos de Poniente] en la Granja de los Saldean, y [La pobre y vieja Blanchy] y [La reliquia olvidada] en la granja de los Cejade.", wp = { { m = 1436, z = "Páramos de Poniente", x = 56.0, y = 31.2, n = "Entregar: Campos de la muerte (Granjero Saldean)", q = 9, a = "T" }, { m = 1436, z = "Páramos de Poniente", x = 56.4, y = 30.5, n = "Entregar: Pastel de hígado de dentosangre (Salma Saldean)", q = 22, a = "T" }, { m = 1436, z = "Páramos de Poniente", x = 56.4, y = 30.5, n = "Entregar: Estofado de los Páramos de Poniente (Salma Saldean)", q = 38, a = "T" }, { m = 1436, z = "Páramos de Poniente", x = 59.9, y = 19.4, n = "Entregar: La pobre y vieja Blanchy (Verna Cejade)", q = 151, a = "T" }, { m = 1436, z = "Páramos de Poniente", x = 60.0, y = 19.4, n = "Entregar: La reliquia olvidada (Granjero Cejade)", q = 64, a = "T" } } },
      { t = "Colina del Centinela: activa el vuelo con Thor y acepta [La hermandad de los Defias] de Gryan Mantorrecio, [Pañuelos rojos de cuero] de Explorador Galiaan y [En patrulla por Páramos de Poniente] de Capitán Danuvin. No cambies la piedra de hogar: la usarás para volver a Thelsamar.", wp = { { m = 1436, z = "Páramos de Poniente", x = 56.5, y = 52.6, n = "Thor", npc = 523 }, { m = 1436, z = "Páramos de Poniente", x = 56.3, y = 47.5, n = "Recoger: La hermandad de los Defias (Gryan Mantorrecio)", q = 65, a = "A" }, { m = 1436, z = "Páramos de Poniente", x = 54.0, y = 53.0, n = "Recoger: Pañuelos rojos de cuero (Explorador Galiaan)", q = 153, a = "A" }, { m = 1436, z = "Páramos de Poniente", x = 56.4, y = 47.6, n = "Recoger: En patrulla por Páramos de Poniente (Capitán Danuvin)", q = 102, a = "A" } } },
      { t = "En la Colina del Centinela, Gryan Mantorrecio te da [Las Milicias del Pueblo]: mata gnolls Zarparrío al oeste de la colina. Entrégala y acepta [Las Milicias del Pueblo], contra los gnolls de más al oeste, y entrégala también.", wp = { { m = 1436, z = "Páramos de Poniente", x = 56.3, y = 47.5, n = "Recoger: Las Milicias del Pueblo (Gryan Mantorrecio)", q = 12, a = "A" }, { m = 1436, z = "Páramos de Poniente", x = 48.5, y = 42.9, n = "Objetivo: Las Milicias del Pueblo", q = 12, a = "C" }, { m = 1436, z = "Páramos de Poniente", x = 56.3, y = 47.5, n = "Entregar: Las Milicias del Pueblo (Gryan Mantorrecio)", q = 12, a = "T" }, { m = 1436, z = "Páramos de Poniente", x = 56.3, y = 47.5, n = "Recoger: Las Milicias del Pueblo (Gryan Mantorrecio)", q = 13, a = "A" }, { m = 1436, z = "Páramos de Poniente", x = 43.6, y = 68.9, n = "Objetivo: Las Milicias del Pueblo", q = 13, a = "C" }, { m = 1436, z = "Páramos de Poniente", x = 56.3, y = 47.5, n = "Entregar: Las Milicias del Pueblo (Gryan Mantorrecio)", q = 13, a = "T" } } },
      { t = "[Pañuelos rojos de cuero] y [En patrulla por Páramos de Poniente]: Defias y gnolls Zarparrío por los campos de Poniente. Entrégalas en la Colina del Centinela.", wp = { { m = 1436, z = "Páramos de Poniente", x = 43.4, y = 69.0, n = "Objetivo: Pañuelos rojos de cuero", q = 153, a = "C" }, { m = 1436, z = "Páramos de Poniente", x = 61.1, y = 73.6, n = "Objetivo: En patrulla por Páramos de Poniente", q = 102, a = "C" }, { m = 1436, z = "Páramos de Poniente", x = 54.0, y = 53.0, n = "Entregar: Pañuelos rojos de cuero (Explorador Galiaan)", q = 153, a = "T" }, { m = 1436, z = "Páramos de Poniente", x = 56.4, y = 47.6, n = "Entregar: En patrulla por Páramos de Poniente (Capitán Danuvin)", q = 102, a = "T" } } },
      { t = "Faro de Poniente (suroeste): Capitán Grisillo te da [Hay moros en la costa] (murlocs de la costa) y [Guardián de la Llama] (la <Botella de aceite> cae de los gólems y vigilantes de la cosecha, en las granjas). Entrégalas en el faro.", wp = { { m = 1436, z = "Páramos de Poniente", x = 30.0, y = 86.0, n = "Recoger: Hay moros en la costa (Capitán Grisillo)", q = 152, a = "A" }, { m = 1436, z = "Páramos de Poniente", x = 30.0, y = 86.0, n = "Recoger: Guardián de la Llama (Capitán Grisillo)", q = 103, a = "A" }, { m = 1436, z = "Páramos de Poniente", x = 27.1, y = 72.4, n = "Objetivo: Hay moros en la costa", q = 152, a = "C" }, { m = 1436, z = "Páramos de Poniente", x = 37.3, y = 50.4, n = "Objetivo: Guardián de la Llama", q = 103, a = "C" }, { m = 1436, z = "Páramos de Poniente", x = 30.0, y = 86.0, n = "Entregar: Hay moros en la costa (Capitán Grisillo)", q = 152, a = "T" }, { m = 1436, z = "Páramos de Poniente", x = 30.0, y = 86.0, n = "Entregar: Guardián de la Llama (Capitán Grisillo)", q = 103, a = "T" } } },
      { t = "Misión extra para no quedarte corto de nivel: [Las Milicias del Pueblo] (nivel 17). Recógela, cumple los objetivos y entrégala.", wp = { { m = 1436, z = "Páramos de Poniente", x = 56.3, y = 47.5, n = "Recoger: Las Milicias del Pueblo (Gryan Mantorrecio)", q = 14, a = "A" }, { m = 1436, z = "Páramos de Poniente", x = 46.4, y = 78.3, n = "Objetivo: Las Milicias del Pueblo", q = 14, a = "C" }, { m = 1436, z = "Páramos de Poniente", x = 56.3, y = 47.5, n = "Entregar: Las Milicias del Pueblo (Gryan Mantorrecio)", q = 14, a = "T" } } }, -- REFUERZO_97 q=14

      { t = "Misión extra en otra zona de tu nivel (Loch Modan): [Recoger ídolos] (nivel 18). Recógela, cumple los objetivos y entrégala.", wp = { { m = 1432, z = "Loch Modan", x = 64.9, y = 66.7, n = "Recoger: Recoger ídolos", q = 297, a = "A" }, { m = 1432, z = "Loch Modan", x = 70.6, y = 64.8, n = "Objetivo: Recoger ídolos", q = 297, a = "C" }, { m = 1432, z = "Loch Modan", x = 64.9, y = 66.7, n = "Entregar: Recoger ídolos", q = 297, a = "T" } } }, -- REFUERZO_97 q=297
