  {
    titulo = "Loch Modan", min = 15, max = 18,
    entrenar = "Talentos: 10-14 Aspectos letales, 15-16 Fuego enfocado (tú y tu mascota hacéis más daño) y 17-19 Entrenamiento de robustez. Tu instructor en el lago es Dargh Endiana, en la Cabaña del Errante (este del lago), con Claude Erksine para tu mascota. Al 12: Disparo Arcano (rango 2), Aliviar mascota (cura a tu mascota: úsalo en cuanto le baje la vida) y Cortar alas; al 16, Mordedura de mangosta y Golpe de raptor (rango 3); al 18, Disparo múltiple, Aspecto del halcón (rango 2) y Picadura de serpiente (rango 3).",
    equipo = "En Thelsamar, Yanni Cuoreforte vende flechas; en la Cabaña del Errante, Jadín del risco vende arcos y carcajes mejores que los de Elwynn. [La fanfarronada de un cazador] te deja elegir: coge el <Arco de caza de Daryl>; el rifle pide aprender armas de fuego. Mazmorras (opcional): las de tu nivel dan mucha experiencia, por sus enemigos y por sus misiones, y conviene hacerlas; tú decides si vas.",
    profesion = "Cobre y estaño en las colinas del lago: con 65 de minería ya puedes minar estaño. Desuello: osos, jabalíes y arañas. Primeros auxilios: <Venda de lino pesado> y, con lana, <Venda de lana>.",
    pasos = {
      { t = "En el puesto de control del sur acepta [En defensa de las tierras del rey] y [La amenaza trogg]. Mata troggs Rompepiedras al este del puesto y entrégalas.", wp = { { m = 1432, z = "Loch Modan", x = 22.1, y = 73.1, n = "Recoger: En defensa de las tierras del rey (Montaraz Pedernal)", q = 224, a = "A" }, { m = 1432, z = "Loch Modan", x = 23.2, y = 73.7, n = "Recoger: La amenaza trogg (Capitán Rugelfuss)", q = 267, a = "A" }, { m = 1432, z = "Loch Modan", x = 32.4, y = 75.0, n = "Objetivo: En defensa de las tierras del rey", q = 224, a = "C" }, { m = 1432, z = "Loch Modan", x = 32.3, y = 75.3, n = "Objetivo: La amenaza trogg", q = 267, a = "C" }, { m = 1432, z = "Loch Modan", x = 22.1, y = 73.1, n = "Entregar: En defensa de las tierras del rey (Montaraz Pedernal)", q = 224, a = "T" }, { m = 1432, z = "Loch Modan", x = 23.2, y = 73.7, n = "Entregar: La amenaza trogg (Capitán Rugelfuss)", q = 267, a = "T" } } },
      { t = "Thelsamar: piedra de hogar en la posada, activa el vuelo con Thorgrum Borrelson y acepta [Mata ratas] y [Morcillas de Thelsamar]. Yanni Cuoreforte, junto a la posada, vende flechas.", wp = { { m = 1432, z = "Loch Modan", x = 35.5, y = 48.4, n = "Tabernero Hogartufa", npc = 6734 }, { m = 1432, z = "Loch Modan", x = 33.9, y = 51.0, n = "Thorgrum Borrelson", npc = 1572 }, { m = 1432, z = "Loch Modan", x = 32.6, y = 49.7, n = "Recoger: Mata ratas (Montaraz Kadrell)", q = 416, a = "A" }, { m = 1432, z = "Loch Modan", x = 34.8, y = 49.3, n = "Recoger: Morcillas de Thelsamar (Vidra Hogartufa)", q = 418, a = "A" }, { m = 1432, z = "Loch Modan", x = 34.8, y = 48.6, n = "Yanni Cuoreforte", npc = 1682 } } },
      { t = "Haz [Morcillas de Thelsamar] (osos, jabalíes y arañas) y [Mata ratas] (ratas del túnel) al norte de Thelsamar.", wp = { { m = 1432, z = "Loch Modan", x = 34.8, y = 33.9, n = "Objetivo: Morcillas de Thelsamar", q = 418, a = "C" }, { m = 1432, z = "Loch Modan", x = 36.5, y = 22.6, n = "Objetivo: Mata ratas", q = 416, a = "C" }, { m = 1432, z = "Loch Modan", x = 34.8, y = 49.3, n = "Entregar: Morcillas de Thelsamar (Vidra Hogartufa)", q = 418, a = "T" }, { m = 1432, z = "Loch Modan", x = 32.6, y = 49.7, n = "Entregar: Mata ratas (Montaraz Kadrell)", q = 416, a = "T" } } },
      { t = "Nivel 12-14: sigue la orilla sur del lago hacia el este hasta la Cabaña del Errante y entrena con Dargh Endiana: Disparo Arcano (rango 2), Aliviar mascota y Cortar alas; con Claude Erksine, al lado, Gran aguante (rango 2) y Armadura natural (rango 2) para tu mascota. Al hablar con el instructor elige entrenar: la guía aprende sola lo recomendado (Mayús para hacerlo a mano).", wp = { { m = 1432, z = "Loch Modan", x = 82.4, y = 62.4, n = "Dargh Endiana", npc = 10930 }, { m = 1432, z = "Loch Modan", x = 82.2, y = 62.8, n = "Claude Erksine", npc = 3545 } }, comprobar = { hechizos = { 136 } } },
      { t = "Cabaña del Errante: [La caza de crocoliscos], [La fanfarronada de un cazador] y [Suministros de Bingles] de Bingles Pimpampum.", wp = { { m = 1432, z = "Loch Modan", x = 81.8, y = 61.7, n = "Recoger: La caza de crocoliscos (Marek Coracero)", q = 385, a = "A" }, { m = 1432, z = "Loch Modan", x = 83.5, y = 65.5, n = "Recoger: La fanfarronada de un cazador (Daryl el Jovenzuelo)", q = 257, a = "A" }, { m = 1432, z = "Loch Modan", x = 63.6, y = 47.9, n = "Recoger: Suministros de Bingles (Bingles Pimpampum)", q = 2038, a = "A" } } },
      { t = "Haz [La fanfarronada de un cazador] rápido (15 min) y luego [El reto de un cazador] (12 min); de recompensa, el <Arco de caza de Daryl>. Cocodrilos del lago para [La caza de crocoliscos].", wp = { { m = 1432, z = "Loch Modan", x = 75.3, y = 73.4, n = "Objetivo: La fanfarronada de un cazador", q = 257, a = "C" }, { m = 1432, z = "Loch Modan", x = 83.5, y = 65.5, n = "Entregar: La fanfarronada de un cazador (Daryl el Jovenzuelo)", q = 257, a = "T" }, { m = 1432, z = "Loch Modan", x = 83.5, y = 65.5, n = "Recoger: El reto de un cazador (Daryl el Jovenzuelo)", q = 258, a = "A" }, { m = 1432, z = "Loch Modan", x = 64.2, y = 39.0, n = "Objetivo: El reto de un cazador", q = 258, a = "C" }, { m = 1432, z = "Loch Modan", x = 83.5, y = 65.5, n = "Entregar: El reto de un cazador (Daryl el Jovenzuelo)", q = 258, a = "T" }, { m = 1432, z = "Loch Modan", x = 63.2, y = 47.7, n = "Objetivo: La caza de crocoliscos", q = 385, a = "C" }, { m = 1432, z = "Loch Modan", x = 81.8, y = 61.7, n = "Entregar: La caza de crocoliscos (Marek Coracero)", q = 385, a = "T" } } },
      { t = "Recoge las herramientas de Bingles en la orilla norte para [Suministros de Bingles].", wp = { { m = 1432, z = "Loch Modan", x = 51.5, y = 23.7, n = "Objetivo: Suministros de Bingles", q = 2038, a = "C" }, { m = 1432, z = "Loch Modan", x = 63.6, y = 47.9, n = "Entregar: Suministros de Bingles (Bingles Pimpampum)", q = 2038, a = "T" } } },
      { t = "Presa del norte: Ingeniero Jefe Hinderweir VII te da [Se aproxima una oscura amenaza]. Busca la pista junto a la rampa este de la presa, vuelve con él y acepta [Se aproxima una oscura amenaza]: se entrega en Los Humedales.", wp = { { m = 1432, z = "Loch Modan", x = 46.0, y = 13.6, n = "Recoger: Se aproxima una oscura amenaza (Ingeniero Jefe Hinderweir VII)", q = 250, a = "A" }, { m = 1432, z = "Loch Modan", x = 56.0, y = 13.2, n = "Entregar: Se aproxima una oscura amenaza (Barril sospechoso)", q = 250, a = "T" }, { m = 1432, z = "Loch Modan", x = 56.0, y = 13.2, n = "Recoger: Se aproxima una oscura amenaza (Barril sospechoso)", q = 199, a = "A" }, { m = 1432, z = "Loch Modan", x = 46.0, y = 13.6, n = "Entregar: Se aproxima una oscura amenaza (Ingeniero Jefe Hinderweir VII)", q = 199, a = "T" }, { m = 1432, z = "Loch Modan", x = 46.0, y = 13.6, n = "Recoger: Se aproxima una oscura amenaza (Ingeniero Jefe Hinderweir VII)", q = 161, a = "A" } } },
      { t = "Fortaleza Mo'grosh (nordeste): ogros élite para [Mercenarios] (Magistrado Romonariz, en Thelsamar): misión difícil, recomendable hacerla en grupo.", wp = { { m = 1432, z = "Loch Modan", x = 34.6, y = 44.5, n = "Recoger: Mercenarios (Magistrado Romonariz)", q = 255, a = "A" }, { m = 1432, z = "Loch Modan", x = 69.9, y = 24.2, n = "Objetivo: Mercenarios", q = 255, a = "C" }, { m = 1432, z = "Loch Modan", x = 34.6, y = 44.5, n = "Entregar: Mercenarios (Magistrado Romonariz)", q = 255, a = "T" } } },
      { t = "Nivel 16: vuelve a la Cabaña del Errante y entrena con Dargh Endiana: Mordedura de mangosta (solo después de esquivar un ataque) y Golpe de raptor (rango 3). Al lado, Jadín del risco vende arcos. Al hablar con el instructor elige entrenar: la guía aprende sola lo recomendado (Mayús para hacerlo a mano).", wp = { { m = 1432, z = "Loch Modan", x = 82.4, y = 62.4, n = "Dargh Endiana", npc = 10930 }, { m = 1432, z = "Loch Modan", x = 83.0, y = 63.0, n = "Jadín del risco", npc = 1687 } }, comprobar = { hechizos = { 1495 } } },
      { t = "Opcional, al 17-18 y en grupo: en el puesto del sur, las dos últimas partes de [En defensa de las tierras del rey]; la última es contra el jefe trogg Grawmug y sus guardias.", wp = { { m = 1432, z = "Loch Modan", x = 23.2, y = 73.7, n = "Capitán Rugelfuss (puesto del sur)", npc = 1092 }, { m = 1432, z = "Loch Modan", x = 34.8, y = 90.5, n = "Gromug, jefe trogg", npc = 1205 } } },
