  {
    titulo = "Vuelta a Ventormenta", min = 20, max = 20,
    entrenar = "Nivel 20 = gran entrenamiento en Ventormenta con Ulfir Barbaférrea, en el Distrito de los Enanos: Disparo de puntería (en Forever lo vende el instructor: ábrelo cada combate con él), Aspecto del guepardo (para viajar), Separación, Trampa congelante, Disparo Arcano (rango 3) y Aliviar mascota (rango 2); con Karrina Mekenda, al lado, Gruñido (rango 3) para tu mascota. Talento 20: Rapidez de bestias (tu mascota corre más).",
    equipo = "Objetivo: completar la cadena [La hermandad de los Defias] hasta Las Minas de la Muerte. En la Colina del Centinela, William MacGregor vende arcos y flechas. Mazmorras (opcional): las de tu nivel dan mucha experiencia, por sus enemigos y por sus misiones, y conviene hacerlas; tú decides si vas.",
    profesion = "Desuello: lobos, jabalíes y buitres de Poniente dan <Cuero ligero> y <Cuero medio>. Minería: cobre y estaño en las colinas. Primeros auxilios: <Venda de lana>.",
    pasos = {
      { t = "Nivel 20: vuela a Ventormenta y entrena en el Distrito de los Enanos con Ulfir Barbaférrea: Disparo de puntería, Aspecto del guepardo, Separación, Trampa congelante, Disparo Arcano (rango 3) y Aliviar mascota (rango 2); con Karrina Mekenda, Gruñido (rango 3) para tu mascota. Al hablar con el instructor elige entrenar: la guía aprende sola lo recomendado (Mayús para hacerlo a mano).", wp = { { m = 1453, z = "Ciudad de Ventormenta", x = 67.6, y = 35.8, n = "Ulfir Barbaférrea", npc = 5516 }, { m = 1453, z = "Ciudad de Ventormenta", x = 67.3, y = 36.8, n = "Karrina Mekenda", npc = 2879 } }, comprobar = { hechizos = { 19434 } } },
    },
  },
  {
    titulo = "Montañas Crestagrana", min = 20, max = 23,
    entrenar = "Pelea así: tu mascota va primero; tú, Marca del cazador, Disparo de puntería, Picadura de serpiente y Disparo Arcano mientras le pega. Si un enemigo va a por ti, Separación para que vuelva con tu mascota, o Cortar alas y aléjate. Al 22: Marca del cazador (rango 2); al 24, Golpe de raptor (rango 4). Talentos 21-24: Furia desatada (tu mascota pega más).",
    equipo = "Busca grupo para Las Minas de la Muerte (entrada en Arroyo de la Luna, Poniente): sus jefes sueltan buenas piezas de cuero. En Villa del Lago, Kimberly Hiett vende flechas y carcajes. Mazmorras (opcional): las de tu nivel dan mucha experiencia, por sus enemigos y por sus misiones, y conviene hacerlas; tú decides si vas.",
    profesion = "Desuello 75-150: <Cuero medio> de cóndores, jabalíes y arañas. Minería: estaño y plata en las colinas de Crestagrana.",
    pasos = {
      { t = "Desde Ventormenta ve al este por Elwynn hasta Villa del Lago. Acepta [Gnolls invasores] en la entrada oeste de la zona; en Villa del Lago activa el vuelo con Ariena Tempespluma, entrega [La hermandad de los Defias] y sigue con [La hermandad de los Defias].", wp = { { m = 1433, z = "Montañas Crestagrana", x = 10.4, y = 71.3, n = "Recoger: Gnolls invasores (Guardia Parker)", q = 244, a = "A" }, { m = 1433, z = "Montañas Crestagrana", x = 25.5, y = 59.4, n = "Ariena Tempespluma", npc = 931 }, { m = 1433, z = "Montañas Crestagrana", x = 21.4, y = 45.4, n = "Entregar: La hermandad de los Defias (Wiley el Negro)", q = 65, a = "T" }, { m = 1433, z = "Montañas Crestagrana", x = 21.4, y = 45.4, n = "Recoger: La hermandad de los Defias (Wiley el Negro)", q = 132, a = "A" } } },
      { t = "Entrega [Gnolls invasores] a Ayudante de alguacil Feldon y acepta [Evaluar la amenaza]: mata gnolls y furtivos al sur.", wp = { { m = 1433, z = "Montañas Crestagrana", x = 25.6, y = 60.0, n = "Entregar: Gnolls invasores (Ayudante de alguacil Feldon)", q = 244, a = "T" }, { m = 1433, z = "Montañas Crestagrana", x = 25.6, y = 60.0, n = "Recoger: Evaluar la amenaza (Ayudante de alguacil Feldon)", q = 246, a = "A" }, { m = 1433, z = "Montañas Crestagrana", x = 26.6, y = 82.6, n = "Objetivo: Evaluar la amenaza", q = 246, a = "C" }, { m = 1433, z = "Montañas Crestagrana", x = 25.6, y = 60.0, n = "Entregar: Evaluar la amenaza (Ayudante de alguacil Feldon)", q = 246, a = "T" } } },
      { t = "[El collar de Hilary]: busca el collar en el fondo del lago. [Las herramientas perdidas]: la caja de herramientas también está en el lago.", wp = { { m = 1433, z = "Montañas Crestagrana", x = 24.2, y = 53.6, n = "Recoger: El collar de Hilary (Shawn)", q = 3741, a = "A" }, { m = 1433, z = "Montañas Crestagrana", x = 24.0, y = 54.1, n = "Objetivo: El collar de Hilary", q = 3741, a = "C" }, { m = 1433, z = "Montañas Crestagrana", x = 24.1, y = 53.6, n = "Entregar: El collar de Hilary (Hilary)", q = 3741, a = "T" }, { m = 1433, z = "Montañas Crestagrana", x = 27.1, y = 48.6, n = "Recoger: Las herramientas perdidas (Supervisor Olento)", q = 125, a = "A" }, { m = 1433, z = "Montañas Crestagrana", x = 36.4, y = 54.7, n = "Objetivo: Las herramientas perdidas", q = 125, a = "C" }, { m = 1433, z = "Montañas Crestagrana", x = 27.1, y = 48.6, n = "Entregar: Las herramientas perdidas (Supervisor Olento)", q = 125, a = "T" } } },
      { t = "[Cazadores furtivos] y [Pescado a la venta] (Maestro de embarcadero Baren, en el muelle): murlocs al este del lago.", wp = { { m = 1433, z = "Montañas Crestagrana", x = 22.6, y = 47.4, n = "Recoger: Cazadores furtivos (Maestro de embarcadero Baren)", q = 150, a = "A" }, { m = 1433, z = "Montañas Crestagrana", x = 22.6, y = 47.4, n = "Recoger: Pescado a la venta (Maestro de embarcadero Baren)", q = 127, a = "A" }, { m = 1433, z = "Montañas Crestagrana", x = 36.5, y = 50.0, n = "Objetivo: Cazadores furtivos", q = 150, a = "C" }, { m = 1433, z = "Montañas Crestagrana", x = 36.5, y = 50.0, n = "Objetivo: Pescado a la venta", q = 127, a = "C" }, { m = 1433, z = "Montañas Crestagrana", x = 22.6, y = 47.4, n = "Entregar: Cazadores furtivos (Maestro de embarcadero Baren)", q = 150, a = "T" }, { m = 1433, z = "Montañas Crestagrana", x = 22.6, y = 47.4, n = "Entregar: Pescado a la venta (Maestro de embarcadero Baren)", q = 127, a = "T" } } },
      { t = "[Estofado de Crestagrana]: cóndores, jabalíes y arañas por toda la zona.", wp = { { m = 1433, z = "Montañas Crestagrana", x = 17.6, y = 43.8, n = "Recoger: Estofado de Crestagrana (Chef Breanna)", q = 92, a = "A" }, { m = 1433, z = "Montañas Crestagrana", x = 48.4, y = 41.8, n = "Objetivo: Estofado de Crestagrana", q = 92, a = "C" }, { m = 1433, z = "Montañas Crestagrana", x = 17.6, y = 43.8, n = "Entregar: Estofado de Crestagrana (Chef Breanna)", q = 92, a = "T" } } },
      { t = "Acepta con el alguacil Marris [La amenaza de los Roca Negra] y [Bloqueo Roca Negra] antes de salir. En los campamentos del este derrota a los orcos y recoge 8 armas robadas y 10 suministros Roca Negra. Entrega ambas a Marris. Aprovecha para reunir al nordeste los colgantes Sombrapiel de [Ley de Salomón].", wp = { { m = 1433, z = "Montañas Crestagrana", x = 28.4, y = 49.0, n = "Recoger: La amenaza de los Roca Negra (Alguacil Marris)", q = 20, a = "A" }, { m = 1433, z = "Montañas Crestagrana", x = 62.5, y = 55.0, n = "Objetivo: La amenaza de los Roca Negra", q = 20, a = "C" }, { m = 1433, z = "Montañas Crestagrana", x = 28.4, y = 49.0, n = "Entregar: La amenaza de los Roca Negra (Alguacil Marris)", q = 20, a = "T" }, { m = 1433, z = "Montañas Crestagrana", x = 24.6, y = 44.3, n = "Recoger: Ley de Salomón (Bailiff Conacher)", q = 91, a = "A" }, { m = 1433, z = "Montañas Crestagrana", x = 73.0, y = 46.2, n = "Objetivo: Ley de Salomón", q = 91, a = "C" }, { m = 1433, z = "Montañas Crestagrana", x = 24.6, y = 44.3, n = "Entregar: Ley de Salomón (Bailiff Conacher)", q = 91, a = "T" }, { m = 1433, z = "Montañas Crestagrana", x = 28.4, y = 49, n = "Recoger: Bloqueo Roca Negra (Alguacil Marris)", q = 98387, a = "A" }, { m = 1433, z = "Montañas Crestagrana", x = 28.4, y = 49, n = "Entregar: Bloqueo Roca Negra (Alguacil Marris)", q = 98387, a = "T" } } },
