  {
    titulo = "Bosque del Ocaso", min = 26, max = 30,
    entrenar = "Al 28: Disparo de puntería (rango 2), Disparo Arcano (rango 4), Aspecto del halcón (rango 3) y Aliviar mascota (rango 3). Al 30: Fingir muerte (los enemigos te dejan: para escapar; en Forever, si no lo cancelas, mueres cuando se acaba) y Mordedura de mangosta (rango 2); tu mascota, Gran aguante (rango 5), Armadura natural (rango 5) y Gruñido (rango 4). Talento 30: Intimidación (tu mascota aturde al enemigo y se lo queda).",
    equipo = "Con grupo: Monasterio Escarlata (30-40), con muchas piezas de cuero y malla. En Villa Oscura, Avette Bosquevil vende arcos y flechas. Mazmorras (opcional): las de tu nivel dan mucha experiencia, por sus enemigos y por sus misiones, y conviene hacerlas; tú decides si vas.",
    profesion = "Desuello: arañas, lobos y huargos dan <Cuero medio> y <Cuero pesado>. Minería: estaño, plata y algo de hierro. Primeros auxilios: <Venda de seda> con el paño de seda.",
    pasos = {
      { t = "Villa Oscura: activa el vuelo con Felicia Maline, pon la piedra de hogar con Tabernera Trelayne y acepta [Vigilancia nocturna], [Kebab de lobo salpimentado] y [El Tótem de castigo].", wp = { { m = 1431, z = "Bosque del Ocaso", x = 77.5, y = 44.3, n = "Felicia Maline", npc = 2409 }, { m = 1431, z = "Bosque del Ocaso", x = 73.9, y = 44.4, n = "Tabernera Trelayne", npc = 6790 }, { m = 1431, z = "Bosque del Ocaso", x = 73.5, y = 46.8, n = "Recoger: Vigilancia nocturna (Comandante Althea Cerranegro)", q = 56, a = "A" }, { m = 1431, z = "Bosque del Ocaso", x = 73.8, y = 43.5, n = "Recoger: Kebab de lobo salpimentado (Chef Grual)", q = 90, a = "A" }, { m = 1431, z = "Bosque del Ocaso", x = 75.8, y = 45.3, n = "Recoger: El Tótem de castigo (Lady Eva)", q = 101, a = "A" } } },
      { t = "Cementerio del este para la primera parte de [Vigilancia nocturna]; la segunda parte te lleva al Cerro del Cuervo.", wp = { { m = 1431, z = "Bosque del Ocaso", x = 79.4, y = 70.8, n = "Objetivo: Vigilancia nocturna", q = 56, a = "C" }, { m = 1431, z = "Bosque del Ocaso", x = 73.5, y = 46.8, n = "Entregar: Vigilancia nocturna (Comandante Althea Cerranegro)", q = 56, a = "T" }, { m = 1431, z = "Bosque del Ocaso", x = 73.5, y = 46.8, n = "Recoger: Vigilancia nocturna (Comandante Althea Cerranegro)", q = 57, a = "A" }, { m = 1431, z = "Bosque del Ocaso", x = 80.6, y = 59.2, n = "Objetivo: Vigilancia nocturna", q = 57, a = "C" }, { m = 1431, z = "Bosque del Ocaso", x = 73.5, y = 46.8, n = "Entregar: Vigilancia nocturna (Comandante Althea Cerranegro)", q = 57, a = "T" } } },
      { t = "Lobos al norte para [Kebab de lobo salpimentado]; en el campamento de Sven, [Con los lobos en los talones].", wp = { { m = 1431, z = "Bosque del Ocaso", x = 66.3, y = 28.6, n = "Objetivo: Kebab de lobo salpimentado", q = 90, a = "C" }, { m = 1431, z = "Bosque del Ocaso", x = 73.8, y = 43.5, n = "Entregar: Kebab de lobo salpimentado (Chef Grual)", q = 90, a = "T" }, { m = 1431, z = "Bosque del Ocaso", x = 7.7, y = 33.2, n = "Recoger: Con los lobos en los talones (Lars)", q = 226, a = "A" }, { m = 1431, z = "Bosque del Ocaso", x = 16.9, y = 27.1, n = "Objetivo: Con los lobos en los talones", q = 226, a = "C" }, { m = 1431, z = "Bosque del Ocaso", x = 7.7, y = 33.2, n = "Entregar: Con los lobos en los talones (Lars)", q = 226, a = "T" } } },
