  {
    titulo = "Las Mil Agujas", min = 30, max = 32,
    entrenar = "Talentos 31-32: Vínculo espiritual (tú y tu mascota recuperáis vida sin parar). En Kalimdor no tienes instructor de cazador hasta Frondavil, pero al 32 no hay nada que haga falta: el siguiente entrenamiento es al 34-36, en Ventormenta.",
    equipo = "Las misiones de El Desierto de Sal dan buenas recompensas de cuero. En la pista solo venden balas: lleva flechas de sobra desde Theramore (Caridad Mipsy las vende). Mazmorras (opcional): las de tu nivel dan mucha experiencia, por sus enemigos y por sus misiones, y conviene hacerlas; tú decides si vas.",
    profesion = "Desuello 150+: <Cuero pesado> de las bestias de Las Mil Agujas. Minería 125-175: hierro y oro en las colinas de Las Mil Agujas y de Tanaris.",
    pasos = {
      { t = "Vuela a Menethil y coge el barco a Theramore (Marjal Revolcafango). Activa el vuelo con Baldruc.", wp = { { m = 1445, z = "Marjal Revolcafango", x = 67.5, y = 51.3, n = "Baldruc", npc = 4321 } }, comprobar = { vuelo = "Theramore" } },
      { t = "Misión extra para no quedarte corto de nivel: [Glándulas de veneno de Nido Alto] (nivel 30). Recógela, cumple los objetivos y entrégala.", wp = { { m = 1445, z = "Marjal Revolcafango", x = 66.5, y = 45.1, n = "Recoger: Glándulas de veneno de Nido Alto", q = 1135, a = "A" }, { m = 1445, z = "Marjal Revolcafango", x = 66.5, y = 45.1, n = "Entregar: Glándulas de veneno de Nido Alto", q = 1135, a = "T" } } }, -- REFUERZO_97 q=1135
