  {
    titulo = "Marjal Revolcafango", min = 39, max = 42,
    entrenar = "Nivel 40: Malla (ya puedes llevarla), Trampa congelante (rango 2), Marca del cazador (rango 3), Golpe de raptor (rango 6) y, para tu mascota, Gruñido (rango 5). Talento 40: Cólera de las bestias (tu mascota hace mucho más daño unos segundos). Al 40 ya puedes montar: guarda oro para la equitación y el caballo.",
    equipo = "Al 40 cambia a malla con Agilidad: las recompensas de cuero ya casi no te sirven. Busca en la subasta piezas de malla 'del mono' o 'del tigre'. Al 40 cambia también las flechas por la <Flecha dentada>: en Theramore la venden Jensen Farran y Caridad Mipsy. Mazmorras (opcional): las de tu nivel dan mucha experiencia, por sus enemigos y por sus misiones, y conviene hacerlas; tú decides si vas.",
    profesion = "En Theramore: [Atenciones médicas] de Primeros auxilios con Doctor Gustaf VanHowzen (225). Desuello y Minería: el Marjal tiene muchas bestias y filones de hierro y mitril.",
    pasos = {
      { t = "Nivel 40: vuela de Costasur a Ventormenta y entrena en el Distrito de los Enanos con Ulfir Barbaférrea: Malla, Trampa congelante (rango 2), Marca del cazador (rango 3) y Golpe de raptor (rango 6); con Karrina Mekenda, Gruñido (rango 5) para tu mascota. Es caro: guarda oro también para la montura. Al hablar con el instructor elige entrenar: la guía aprende sola lo recomendado (Mayús para hacerlo a mano).", wp = { { m = 1453, z = "Ciudad de Ventormenta", x = 67.6, y = 35.8, n = "Ulfir Barbaférrea", npc = 5516 } }, comprobar = { hechizos = { 8737 } } },
      { t = "Montura: sal de Ventormenta y ve al este de Elwynn. En el campamento maderero del este aprende equitación con Randal Predatio y compra un caballo a Katie Hunter.", wp = { { m = 1429, z = "Bosque de Elwynn", x = 84.3, y = 64.9, n = "Randal Predatio", npc = 4732 }, { m = 1429, z = "Bosque de Elwynn", x = 84.2, y = 65.5, n = "Katie Hunter", npc = 384 } } },
      { t = "Vuela a Menethil y coge el barco a Theramore. Compra 3 <Especias calmantes> a Helenia Olden, que las pedirá \"Ojolodo\" Jarl. Morgan Stern te da [Sopa de fangorroca con tropezones]: tortugas Fangorroca en la costa del Marjal. La segunda parte ([... con tropezones]) es del Pantano de las Penas: no la cojas.", wp = { { m = 1445, z = "Marjal Revolcafango", x = 66.4, y = 51.5, n = "Helenia Olden", npc = 4897 }, { m = 1445, z = "Marjal Revolcafango", x = 66.3, y = 45.5, n = "Recoger: Sopa de fangorroca con tropezones (Morgan Stern)", q = 1204, a = "A" }, { m = 1445, z = "Marjal Revolcafango", x = 59.5, y = 52.9, n = "Objetivo: Sopa de fangorroca con tropezones", q = 1204, a = "C" }, { m = 1445, z = "Marjal Revolcafango", x = 66.3, y = 45.5, n = "Entregar: Sopa de fangorroca con tropezones (Morgan Stern)", q = 1204, a = "T" } } },
      { t = "Marjal: [¡Qué hambre!] (cabezas de aleta de fango al norte).", wp = { { m = 1445, z = "Marjal Revolcafango", x = 35.1, y = 38.3, n = "Recoger: ¡Qué hambre! (Fangolpe Piesucio)", q = 1177, a = "A" }, { m = 1445, z = "Marjal Revolcafango", x = 57.7, y = 15.2, n = "Objetivo: ¡Qué hambre!", q = 1177, a = "C" }, { m = 1445, z = "Marjal Revolcafango", x = 35.1, y = 38.3, n = "Entregar: ¡Qué hambre! (Fangolpe Piesucio)", q = 1177, a = "T" } } },
      { t = "Pantano de la Luz: dale las especias a \"Ojolodo\" Jarl ([Especias calmantes]) y haz [Jarl necesita ojos]: arañas Niebla Negra, al oeste.", wp = { { m = 1445, z = "Marjal Revolcafango", x = 55.4, y = 26.3, n = "Recoger: Especias calmantes (\"Ojolodo\" Jarl)", q = 1218, a = "A" }, { m = 1445, z = "Marjal Revolcafango", x = 55.4, y = 26.3, n = "Entregar: Especias calmantes (\"Ojolodo\" Jarl)", q = 1218, a = "T" }, { m = 1445, z = "Marjal Revolcafango", x = 55.4, y = 26.3, n = "Recoger: Jarl necesita ojos (\"Ojolodo\" Jarl)", q = 1206, a = "A" }, { m = 1445, z = "Marjal Revolcafango", x = 32.6, y = 22.1, n = "Objetivo: Jarl necesita ojos", q = 1206, a = "C" }, { m = 1445, z = "Marjal Revolcafango", x = 55.4, y = 26.3, n = "Entregar: Jarl necesita ojos (\"Ojolodo\" Jarl)", q = 1206, a = "T" } } },
      { t = "Al noroeste del Pantano de la Luz, Ignatz el \"Apestoso\" te pide que lo escoltes ([La fuga de Apestoso]). Al acabar, habla con Morgan Stern en Theramore.", wp = { { m = 1445, z = "Marjal Revolcafango", x = 46.9, y = 17.5, n = "Recoger: La fuga de Apestoso (Ignatz el \"Apestoso\")", q = 1222, a = "A" }, { m = 1445, z = "Marjal Revolcafango", x = 66.3, y = 45.5, n = "Entregar: La fuga de Apestoso (Morgan Stern)", q = 1222, a = "T" } } },
