  {
    titulo = "Frondavil y Cuna del Invierno", min = 55, max = 58,
    entrenar = "Al 54, para tu mascota: Gran aguante (rango 9) y Armadura natural (rango 9); al 56, Golpe de raptor (rango 8). Talentos 56-60: Disparos mortales (tus críticos a distancia hacen más daño).",
    equipo = "Las misiones de Cuna del Invierno dan anillos y capas. Flechas: Malygen, junto al vuelo del norte de Frondavil (en Vista Eterna solo venden balas). Mazmorras (opcional): las de tu nivel dan mucha experiencia, por sus enemigos y por sus misiones, y conviene hacerlas; tú decides si vas.",
    profesion = "Minería: torio rico en Cuna del Invierno. Desuello: yetis, osos y quimeras dan <Cuero basto>.",
    pasos = {
      { t = "Frondavil: [Limpiar Frondavil] y [Investigación acerca de la corrupción].", wp = { { m = 1448, z = "Frondavil", x = 54.1, y = 86.8, n = "Recoger: Limpiar Frondavil (Arathandris Cielargente)", q = 4101, a = "A" }, { m = 1448, z = "Frondavil", x = 50.9, y = 81.6, n = "Recoger: Investigación acerca de la corrupción (Taronn Plumarroja)", q = 5156, a = "A" }, { m = 1448, z = "Frondavil", x = 42.5, y = 40.3, n = "Objetivo: Investigación acerca de la corrupción", q = 5156, a = "C" }, { m = 1448, z = "Frondavil", x = 50.9, y = 81.6, n = "Entregar: Investigación acerca de la corrupción (Taronn Plumarroja)", q = 5156, a = "T" }, { m = 1448, z = "Frondavil", x = 57.5, y = 19.6, n = "Objetivo: Limpiar Frondavil", q = 4101, a = "C" }, { m = 1448, z = "Frondavil", x = 54.1, y = 86.8, n = "Entregar: Limpiar Frondavil (Arathandris Cielargente)", q = 4101, a = "T" } } },
      { t = "Sube al norte por Frondavil y activa el vuelo con Mishellena. Al lado, entrena con Kaerbrus: Disparo de puntería (rango 5), Disparo Arcano (rango 7), Aliviar mascota (rango 6) y, al 56, Golpe de raptor (rango 8); con Nalesette Asilvestra, lo de tu mascota del 48 y del 54. Después cruza el Bastión de los Fauces de Madera hasta Cuna del Invierno. Al hablar con el instructor elige entrenar: la guía aprende sola lo recomendado (Mayús para hacerlo a mano).", wp = { { m = 1448, z = "Frondavil", x = 62.5, y = 24.2, n = "Mishellena", npc = 12578 }, { m = 1448, z = "Frondavil", x = 61.9, y = 23.6, n = "Kaerbrus", npc = 5501 }, { m = 1448, z = "Frondavil", x = 62.2, y = 24.4, n = "Nalesette Asilvestra", npc = 543 } }, comprobar = { hechizos = { 20903 } } },
