  {
    titulo = "Tierras de la Peste", min = 58, max = 60,
    entrenar = "Al 58: Aspecto del halcón (rango 6), Marca del cazador (rango 4), Mordedura de mangosta (rango 4) y Picadura de serpiente (rango 8). Al 60 compra los rangos finales: Disparo de puntería, Disparo Arcano, Aliviar mascota, Trampa congelante y Cortar alas. Reparto final de talentos: 31 Bestias / 20 Puntería.",
    equipo = "A 60: Stratholme, Scholomance y Profundidades de Roca Negra. En Forever muchos objetos cambiaron: compara en Wowhead (sección Forever) antes de elegir. Compra las flechas en Forjaz, con Skolmin Furiadorada, cuando vayas a entrenar. Mazmorras (opcional): las de tu nivel dan mucha experiencia, por sus enemigos y por sus misiones, y conviene hacerlas; tú decides si vas.",
    profesion = "Minería y Desuello a 300: el torio y el cuero basto se venden muy bien.",
    pasos = {
      { t = "Vuelve a los Reinos del Este: vuela de Vista Eterna a Auberdine, coge el barco a Menethil y vuela a Forjaz. Entrena con Olmin Barbanllamas todo lo que te falte: Aspecto del halcón (rango 6), Marca del cazador (rango 4), Mordedura de mangosta (rango 4) y Picadura de serpiente (rango 8); con Belia Tronagranito, lo de tu mascota. Al hablar con el instructor elige entrenar: la guía aprende sola lo recomendado (Mayús para hacerlo a mano).", wp = { { m = 1455, z = "Forjaz", x = 70.9, y = 83.6, n = "Olmin Barbanllamas", npc = 5116 } }, comprobar = { hechizos = { 14322 } } },
