  { d = 10, h = 14, rama = "Bestias", fila = 1, nombre = "Aspectos letales (Deadly Aspects)", puntos = "5/5", nota = "Nuevo en Forever: con Aspecto del halcón, tu Disparo automático puede darte más velocidad de disparo unos segundos.", icono = "Interface\\Icons\\Spell_Nature_RavenForm" },
  { d = 15, h = 16, rama = "Bestias", fila = 2, nombre = "Fuego enfocado (Focused Fire)", puntos = "2/2", nota = "Nuevo: tú y tu mascota hacéis más daño mientras está fuera.", icono = "Interface\\Icons\\INV_Weapon_Crossbow_10" },
  { d = 17, h = 19, rama = "Bestias", fila = 1, nombre = "Entrenamiento de robustez (Endurance Training)", puntos = "3/5", nota = "Más vida y armadura para tu mascota. Con estos 10 puntos abres la fila 3.", icono = "Interface\\Icons\\Spell_Nature_Reincarnation" },
  { d = 20, h = 20, rama = "Bestias", fila = 3, nombre = "Rapidez de bestias (Bestial Swiftness)", puntos = "1/1", nota = "Tu mascota corre más y llega antes a los enemigos. Hace falta para Intimidación.", icono = "Interface\\Icons\\Ability_Druid_Dash" },
  { d = 21, h = 24, rama = "Bestias", fila = 3, nombre = "Furia desatada (Unleashed Fury)", puntos = "4/5", nota = "Tu mascota hace más daño. Con estos 15 puntos abres la fila 4.", icono = "Interface\\Icons\\Ability_BullRush" },
