  { d = 30, h = 30, rama = "Bestias", fila = 5, nombre = "Intimidación (Intimidation)", puntos = "1/1", nota = "Tu mascota aturde al enemigo con su siguiente golpe y se lo queda: úsalo cuando un enemigo vaya a por ti.", icono = "Interface\\Icons\\Ability_Devour" },
