R.profesiones = {
  { nombre = "Minería", skill = 186, icono = "Interface\\Icons\\Trade_Mining", intro = "Mina cada veta que veas: da puntos y oro para los entrenamientos. Fundir en una forja también da puntos. Rangos: aprendiz con Kelsey Fargo en la entrada de la Mina del Eco (también vende el <Pico de minero>); oficial con Gelman Petramano en el Distrito de los Enanos de Ventormenta o con Geofram Dedorroca en Forjaz (minería 50 y nivel 10); experto y artesano con Geofram Dedorroca (125 y nivel 20; 200 y nivel 25).", pasos = {
    { d = 1, h = 65, icono = "Interface\\Icons\\inv_ore_copper_01", t = "<Mineral de cobre>: vetas de cobre de Elwynn, Loch Modan y Poniente. Funde <Lingote de cobre> (1 <Mineral de cobre>) en la forja de Villadorada, de Ventormenta o de Forjaz. A 50 aprende el rango oficial.", crea = { 2770, 2840 } },
    { d = 65, h = 125, icono = "Interface\\Icons\\inv_ore_tin_01", t = "<Mineral de estaño> y <Mineral de plata>: vetas de estaño y de plata en Crestagrana, Los Humedales y el Bosque del Ocaso. Funde <Lingote de estaño> (1 <Mineral de estaño>), <Lingote de plata> (1 <Mineral de plata>) y <Lingote de bronce> (1 <Lingote de cobre> y 1 <Lingote de estaño>). A 125 aprende el rango experto.", crea = { 2771, 3576, 2842, 2841 } },
    { d = 125, h = 175, icono = "Interface\\Icons\\inv_ore_iron_01", t = "<Hierro> y <Mineral de oro>: filones de hierro y de oro en Desolace, Las Mil Agujas, la Vega de Tuercespina y Arathi. Funde <Lingote de hierro> (1 <Hierro>) y <Lingote de oro> (1 <Mineral de oro>).", crea = { 2772, 3575, 3577 } },
    { d = 175, h = 250, icono = "Interface\\Icons\\inv_ore_mithril_02", t = "<Mineral de mitril>: filones de mitril en Tanaris, Feralas, las Tierras del Interior y las Tierras Inhóspitas. Funde <Lingote de mitril> (1 <Mineral de mitril>). A 200 aprende el rango artesano. Desde 230 también la veraplata: <Lingote de veraplata> (1 <Veraplata>).", crea = { 3858, 3860, 6037 } },
    { d = 250, h = 300, icono = "Interface\\Icons\\inv_ore_thorium_02", t = "<Torio>: vetas pequeñas de torio en Un'Goro, Frondavil, Cuna del Invierno y las Tierras de la Peste; desde 275, también las ricas. Funde <Lingote de torio> (1 <Torio>).", crea = { 10620, 12359 } },
  } },
  { nombre = "Desuello", skill = 393, icono = "Interface\\Icons\\INV_Misc_Pelt_Wolf_01", intro = "Desuella todas las bestias que mates: el cuero se vende bien. Las de nivel 10 o menos valen desde el principio; después, nivel 20 pide 100, nivel 30 pide 150, nivel 40 pide 200 y así hasta 300. Rangos: aprendiz con Riley Desollapelambres, al oeste de la abadía de Villanorte (también vende el <Cuchillo para desollar>); oficial con Maris Granger en el Casco Antiguo de Ventormenta o con Balthus Cazarrocas en Forjaz (50 y nivel 10); experto y artesano con Balthus Cazarrocas (125 y nivel 20; 200 y nivel 25).", pasos = {
    { d = 1, h = 75, icono = "Interface\\Icons\\inv_misc_leatherscrap_03", t = "<Cuero ligero> y <Restos de cuero estropeado>: lobos, jabalíes y osos de Elwynn y Loch Modan. En Villadorada, [Pieles de lobo bastas] pide pieles de lobo. A 50 aprende el rango oficial con Maris Granger o con Balthus Cazarrocas.", crea = { 2318 } },
    { d = 75, h = 150, icono = "Interface\\Icons\\inv_misc_leatherscrap_05", t = "<Cuero medio>: bestias de Poniente, Crestagrana, Los Humedales y el Bosque del Ocaso. A 125 aprende el rango experto.", crea = { 2319 } },
    { d = 150, h = 225, icono = "Interface\\Icons\\inv_misc_leatherscrap_07", t = "<Cuero pesado>: bestias de Las Mil Agujas, Desolace, la Vega de Tuercespina, Arathi y el Marjal Revolcafango. A 200 aprende el rango artesano.", crea = { 4234 } },
    { d = 225, h = 300, icono = "Interface\\Icons\\inv_misc_leatherscrap_08", t = "<Cuero grueso> y después <Cuero basto>: bestias de Tanaris, Feralas, las Tierras del Interior, Un'Goro y Cuna del Invierno.", crea = { 4304 } },
  } },
  { nombre = "Primeros auxilios", skill = 129, icono = "Interface\\Icons\\Spell_Holy_SealOfSacrifice", intro = "No ocupa una de tus dos profesiones y en Forever también hace pociones de curación. Instructores: Michelle Belle en Villadorada, Shaina Fuller en la Plaza de la Catedral de Ventormenta y Nissa Pirorroca en Forjaz. A 125 compra <Primeros auxilios para expertos: Entre vendas> a Deneb Camino en Stromgarde (Arathi). A 225 haz [Atenciones médicas] con Doctor Gustaf VanHowzen en Theramore (nivel 35).", pasos = {
    { d = 1, h = 40, icono = "Interface\\Icons\\inv_misc_bandage_15", t = "<Venda de lino> (1 <Paño de lino>). Con hierbas también vale <Poción de curación menor> (<Flor de paz>, <Especias suaves> y <Vial vacío>) hasta 75.", mat = { { 2589, 1, "Paño de lino" } }, crea = { 1251, 118 } },
    { d = 40, h = 80, icono = "Interface\\Icons\\inv_misc_bandage_18", t = "<Venda de lino pesado> (2 <Paño de lino>).", mat = { { 2589, 2, "Paño de lino" } }, crea = { 2581 } },
